def trace(capacity, ops):
    cache = OrderedDict()
    results = []
    evicted = []
    hits = 0
    misses = 0

    for op in ops:
        if op[0] == "put":
            _, key, value = op
            if key in cache:
                # Update value but do NOT refresh recency
                cache[key] = value
            else:
                # Insert new key as most-recently-used
                if len(cache) >= capacity:
                    # Evict least recently used (first item)
                    evicted_key, _ = cache.popitem(last=False)
                    evicted.append(evicted_key)
                cache[key] = value
        elif op[0] == "get":
            _, key = op
            if key in cache:
                # Move to end (most recently used)
                cache.move_to_end(key)
                results.append(cache[key])
                hits += 1
            else:
                results.append(None)
                misses += 1
        elif op[0] == "peek":
            _, key = op
            if key in cache:
                # Do NOT move to end; just read the value
                results.append(cache[key])
                hits += 1
            else:
                results.append(None)
                misses += 1

    return {
        "results": results,
        "evicted": evicted,
        "hits": hits,
        "misses": misses
    }

