def price(base, rules):
    current = base
    total_discount = 0
    for rule in rules:
        if rule[0] == "percent":
            p = rule[1]
            discount = (current * p) // 100
            current -= discount
            total_discount += discount
        elif rule[0] == "flat":
            f = rule[1]
            actual_discount = min(f, current)
            current -= actual_discount
            total_discount += actual_discount
        elif rule[0] == "cap":
            c = rule[1]
            if total_discount > c:
                current = base - c
                total_discount = c
    return current

