def table(results):
    # Validate input
    if not results:
        return []

    for home, away, home_goals, away_goals in results:
        if home_goals < 0 or away_goals < 0:
            raise ValueError("Negative goal count")
        if home == away:
            raise ValueError("Team plays itself")

    # Collect all teams and their stats
    teams = {}

    for home, away, home_goals, away_goals in results:
        # Initialize home team if not present
        if home not in teams:
            teams[home] = {'points': 0, 'goals_for': 0, 'goals_against': 0, 'games_played': 0}
        # Initialize away team if not present
        if away not in teams:
            teams[away] = {'points': 0, 'goals_for': 0, 'goals_against': 0, 'games_played': 0}

        # Update home team stats
        teams[home]['goals_for'] += home_goals
        teams[home]['goals_against'] += away_goals
        teams[home]['games_played'] += 1

        # Update away team stats
        teams[away]['goals_for'] += away_goals
        teams[away]['goals_against'] += home_goals
        teams[away]['games_played'] += 1

        # Update points
        if home_goals > away_goals:
            teams[home]['points'] += 3
        elif home_goals < away_goals:
            teams[away]['points'] += 3
        else:
            teams[home]['points'] += 1
            teams[away]['points'] += 1

    # Build head-to-head points map: for each pair (a, b), store points a got against b
    # h2h[(a, b)] = points a earned in matches between a and b
    h2h = {}
    for home, away, home_goals, away_goals in results:
        # Points home got against away
        if home_goals > away_goals:
            home_pts = 3
            away_pts = 0
        elif home_goals < away_goals:
            home_pts = 0
            away_pts = 3
        else:
            home_pts = 1
            away_pts = 1

        # Accumulate
        h2h[(home, away)] = h2h.get((home, away), 0) + home_pts
        h2h[(away, home)] = h2h.get((away, home), 0) + away_pts

    # Group teams by points
    from collections import defaultdict
    points_groups = defaultdict(list)
    for team, stats in teams.items():
        points_groups[stats['points']].append(team)

    # Fallback sort key for a team
    def fallback_key(team):
        stats = teams[team]
        goal_diff = stats['goals_for'] - stats['goals_against']
        # Sort by: goal_diff desc, goals_for desc, games_played asc, name asc
        return (-goal_diff, -stats['goals_for'], stats['games_played'], team)

    # Process each points group
    result = []
    for pts in sorted(points_groups.keys(), reverse=True):
        group = points_groups[pts]
        if len(group) == 1:
            result.append(group[0])
        elif len(group) == 2:
            a, b = group
            # Get head-to-head points
            a_vs_b = h2h.get((a, b), 0)
            b_vs_a = h2h.get((b, a), 0)

            if a_vs_b > b_vs_a:
                result.append(a)
                result.append(b)
            elif b_vs_a > a_vs_b:
                result.append(b)
                result.append(a)
            else:
                # Head-to-head points are level (including never met)
                # Use fallback chain
                sorted_group = sorted(group, key=fallback_key)
                result.extend(sorted_group)
        else:
            # 3 or more teams: use fallback chain
            sorted_group = sorted(group, key=fallback_key)
            result.extend(sorted_group)

    return result

