    b_parts, b_tag = parse_version(b)

    # Pad the shorter numeric list with zeros
    max_len = max(len(a_parts), len(b_parts))
    while len(a_parts) < max_len:
        a_parts.append(0)
    while len(b_parts) < max_len:
        b_parts.append(0)

    # Compare numeric components
    for i in range(max_len):
        if a_parts[i] < b_parts[i]:
            return -1
        elif a_parts[i] > b_parts[i]:
            return 1

    # Numeric parts are equal; now compare pre-release tags
    # A pre-release sorts BEFORE its release (no tag)
    if a_tag is None and b_tag is None:
        return 0
    elif a_tag is None and b_tag is not None:
        # a is a release, b is a pre-release: a is newer
        return 1
    elif a_tag is not None and b_tag is None:
        # a is a pre-release, b is a release: a is older
        return -1
    else:
        # Both have pre-release tags: compare using run-based rule
        return compare_tags(a_tag, b_tag)

import re


def cmp(a: str, b: str) -> int:
    """
    Compare two dotted numeric version strings, with optional pre-release suffixes.

    Args:
        a: First version string (e.g., "1.2.10" or "1.2.0-beta")
        b: Second version string (e.g., "1.2.9" or "1.2.0-alpha")

    Returns:
        -1 if a is older than b
        1 if a is newer than b
        0 if they are the same version

    Raises:
        ValueError: If either argument is an invalid version string.
    """
    def validate_and_parse(s: str):
        """
        Validate and parse a version string.
        Returns (numeric_parts, prerelease_tag) or raises ValueError.
        """
        if not s:
            raise ValueError("Empty version string")

        # Split off the pre-release tag at the first '-'
        if '-' in s:
            numeric_part, tag = s.split('-', 1)
            if not tag:
                raise ValueError("Empty pre-release tag")
        else:
            numeric_part, tag = s, None

        # Validate and parse numeric components
        if not numeric_part:
            raise ValueError("Empty numeric part")

        components = numeric_part.split('.')
        parts = []
        for comp in components:
            if not comp:
                raise ValueError("Empty numeric component")
            if not all(c in '0123456789' for c in comp):
                raise ValueError(f"Invalid numeric component: {comp}")
            parts.append(int(comp))

        return parts, tag

    def split_tag_runs(tag: str):
        """
        Split a tag into maximal runs of consecutive digits and non-digits.
        Returns a list of (is_digit, value) tuples.
        """
        runs = []
        for match in re.finditer(r'\d+|\D+', tag):
            s = match.group()
            if s.isdigit():
                runs.append((True, int(s)))
            else:
                runs.append((False, s))
        return runs

    def compare_tags(tag_a: str, tag_b: str) -> int:
        """
        Compare two pre-release tags using the run-based rule.
        Returns -1, 0, or 1.
        """
        runs_a = split_tag_runs(tag_a)
        runs_b = split_tag_runs(tag_b)

        max_len = max(len(runs_a), len(runs_b))

        for i in range(max_len):
            if i >= len(runs_a):
                # runs_a is a prefix of runs_b: shorter is older
                return -1
            if i >= len(runs_b):
                # runs_b is a prefix of runs_a: shorter is older
                return 1

            is_digit_a, val_a = runs_a[i]
            is_digit_b, val_b = runs_b[i]

            if is_digit_a and is_digit_b:
                # Both digit runs: compare numerically
                if val_a < val_b:
                    return -1
                elif val_a > val_b:
                    return 1
            elif not is_digit_a and not is_digit_b:
                # Both non-digit runs: compare lexicographically
                if val_a < val_b:
                    return -1
                elif val_a > val_b:
                    return 1
            else:
                # One is digit, one is non-digit: digit sorts BEFORE non-digit
                if is_digit_a:
                    return -1
                else:
                    return 1

        # All runs are equal
        return 0

    a_parts, a_tag = validate_and_parse(a)
    b_parts, b_tag = validate_and_parse(b)

    # Pad the shorter numeric list with zeros
    max_len = max(len(a_parts), len(b_parts))
    while len(a_parts) < max_len:
        a_parts.append(0)
    while len(b_parts) < max_len:
        b_parts.append(0)

    # Compare numeric components
    for i in range(max_len):
        if a_parts[i] < b_parts[i]:
            return -1
        elif a_parts[i] > b_parts[i]:
            return 1

    # Numeric parts are equal; now compare pre-release tags
    # A pre-release sorts BEFORE its release (no tag)
    if a_tag is None and b_tag is None:
        return 0
    elif a_tag is None and b_tag is not None:
        # a is a release, b is a pre-release: a is newer
        return 1
    elif a_tag is not None and b_tag is None:
        # a is a pre-release, b is a release: a is older
        return -1
    else:
        # Both have pre-release tags: compare using run-based rule
        return compare_tags(a_tag, b_tag)

def wrap(text, width):
    words = text.split()
    if not words:
        return []

    # Pre-process: break any word longer than width into chunks of exactly width
    processed_words = []
    for word in words:
        if len(word) <= width:
            processed_words.append(word)
        else:
            # Hard-break into chunks of exactly width characters
            for i in range(0, len(word), width):
                processed_words.append(word[i:i + width])

    lines = []
    current_line = []
    current_length = 0

    for word in processed_words:
        word_len = len(word)

        # If the current line is empty, start with this word
        if not current_line:
            current_line.append(word)
            current_length = word_len
        else:
            # Check if adding this word would exceed width
            # New length would be current_length + 1 (space) + word_len
            if current_length + 1 + word_len <= width:
                current_line.append(word)
                current_length += 1 + word_len
            else:
                # Start a new line
                lines.append(' '.join(current_line))
                current_line = [word]
                current_length = word_len

    # Don't forget the last line
    if current_line:
        lines.append(' '.join(current_line))

    return lines
